// ---------- pricing.hpp ----------
#ifndef LOWLATENCY_PRICING_HPP
#define LOWLATENCY_PRICING_HPP

struct Order {
    double bid;
    double ask;
};

// Defined here: every including translation unit gets a copy, and the ODR
// allows that for an inline function as long as the definitions match.
inline double mid(double bid, double ask) {
    return (bid + ask) / 2.0;
}

// Declared only: exactly one translation unit may define it.
double spread_bps(const Order& order);

// Declaration, not a definition: no storage is allocated here.
extern int tick_count;

#endif

// ---------- pricing.cpp ----------
#include <cmath>

int tick_count = 0;  // the one definition in the program

double spread_bps(const Order& order) {
    ++tick_count;
    return 10'000.0 * std::abs(order.ask - order.bid)
           / mid(order.bid, order.ask);
}

// SQUARE(a + b) expanded to a + b * a + b: the preprocessor substitutes
// tokens before the compiler knows about precedence. A function evaluates
// its argument first.
constexpr int square(int value) {
    return value * value;
}

// GREATER(++sequence, -1) substituted ++sequence into two places and
// incremented twice. A function has parameter objects, so each argument is
// evaluated exactly once.
template<class T>
constexpr const T& greater_of(const T& lhs, const T& rhs) {
    return lhs > rhs ? lhs : rhs;
}

// Conditional compilation is the use the preprocessor keeps: there is no
// language-level way to select this at translation time.
#ifdef NDEBUG
inline constexpr bool diagnostics_enabled = false;
#else
inline constexpr bool diagnostics_enabled = true;
#endif

// ---------- limits.hpp ----------
#ifndef LOWLATENCY_LIMITS_HPP
#define LOWLATENCY_LIMITS_HPP

// Definition. inline (C++17) makes every including translation unit refer to
// one entity rather than each getting a private copy.
inline constexpr int max_symbols = 4096;

// Declaration only. Exactly one definition may exist in the whole program.
extern int tick_count;

// Definition. A class may be defined in many translation units provided
// every definition is the same one.
struct Order {
    double bid;
    double ask;
};

// Definition. May appear in many translation units, but the token sequences
// must match: `return (bid + ask) / 2.0;` and `return (ask + bid) / 2.0;`
// in two headers would be an ODR violation even though the results agree.
inline double mid(double bid, double ask) {
    return (bid + ask) / 2.0;
}

#endif

// ---------- limits.cpp ----------
int tick_count = 0;  // the program's one definition of tick_count

#include <cstddef>

// static duration, namespace scope, external linkage. Another translation
// unit that writes `extern std::size_t total_messages;` denotes this object.
std::size_t total_messages = 0;

namespace {

// Internal linkage: another .cpp may spell `normalize` too, and it will be a
// different function. Functions have no storage duration at all — that
// classification applies to objects and references.
double normalize(double price) {
    return price < 0.0 ? 0.0 : price;
}

}  // namespace

double record(double price) {
    // static duration (lives for the whole program), block scope (the name is
    // visible only here), no linkage (nothing elsewhere can denote it).
    static std::size_t call_count = 0;
    ++call_count;

    ++total_messages;
    return normalize(price);
}

namespace {

// Anonymous namespace: internal linkage for the type as well as the
// function. Namespace-scope `static` would localise clamp_price but has no
// way to localise the class — and two .cpp files each defining their own
// `struct Helper` at namespace scope is an ODR violation that commonly
// links clean and misbehaves at run time.
struct Helper {
    int value;

    void normalize() { value = 0; }
};

double clamp_price(double price) {
    return price < 0.0 ? 0.0 : price;
}

}  // namespace

// The only name this translation unit publishes.
double normalized_price(double price) {
    Helper helper{1};
    helper.normalize();
    return clamp_price(price) + helper.value;
}

