#ifdef __cplusplus
extern "C" {
#endif

// Opaque handle: the concrete layout stays on the library's side.
typedef struct session_handle session_handle;

// C linkage means one flat symbol per name — these cannot be overloaded,
// and they must trade in C-compatible values and pointers rather than
// references or classes with constructors and destructors.
session_handle* session_create(const char* endpoint);
void session_send(session_handle* handle, int order_id);
void session_destroy(session_handle* handle);

#ifdef __cplusplus
}
#endif

// ---------- session_c.cpp ----------
struct session_handle {
    std::string endpoint;
    std::vector<int> pending;
};

extern "C" session_handle* session_create(const char* endpoint) {
    return new session_handle{endpoint, {}};
}

extern "C" void session_send(session_handle* handle, int order_id) {
    handle->pending.push_back(order_id);
}

// The library that created the object must also destroy it, so allocation
// and runtime-library ownership never cross the boundary inconsistently.
extern "C" void session_destroy(session_handle* handle) {
    delete handle;
}

