#pragma once

#include <memory>
#include <string_view>

class Session {
public:
    explicit Session(std::string_view endpoint);

    // Declared here, defined in the .cpp: destroying a unique_ptr<Impl>
    // needs Impl to be complete, and it deliberately is not complete here.
    ~Session();

    Session(Session&&) noexcept;
    Session& operator=(Session&&) noexcept;

    Session(const Session&) = delete;
    Session& operator=(const Session&) = delete;

    void send(int order_id);

private:
    class Impl;                   // declaration only
    std::unique_ptr<Impl> impl_;  // stable outer size
};

// ---------- session.cpp ----------
#include <string>
#include <utility>
#include <vector>

class Session::Impl {
public:
    explicit Impl(std::string_view endpoint) : endpoint_(endpoint) {}

    void send(int order_id) { pending_.push_back(order_id); }

private:
    std::string endpoint_;
    std::vector<int> pending_;
};

Session::Session(std::string_view endpoint)
    : impl_(std::make_unique<Impl>(endpoint)) {}

// Defined where Impl is complete; `= default` is enough.
Session::~Session() = default;
Session::Session(Session&&) noexcept = default;
Session& Session::operator=(Session&&) noexcept = default;

void Session::send(int order_id) {
    impl_->send(order_id);
}

// Build the library with: -DPRICING_BUILD -fvisibility=hidden
// Consumers compile without PRICING_BUILD.
#if defined(PRICING_BUILD)
#define PRICING_API __attribute__((visibility("default")))
#else
#define PRICING_API
#endif

struct Order;

PRICING_API double spread_bps(const Order& order);
PRICING_API extern int tick_count;

